import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick }) {
  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '👨‍🎓' },
    { name: 'Manage Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Feedback', icon: '💬' }
  ];

  return (
    <div style={{
      width: '260px',
      height: '100%', // මව් div එකේ හයිට් එකටම හැඩගැසීමට 100% කළා
      backgroundColor: '#15803d',
      color: '#ffffff',
      display: 'flex',
      flexDirection: 'column',
      boxShadow: '4px 0 10px rgba(0,0,0,0.1)'
    }}>
      {/* Header කොටස */}
      <div style={{ padding: '25px', borderBottom: '1px solid rgba(255,255,255,0.1)', textAlign: 'center' }}>
        <h2 style={{ fontSize: '20px', margin: 0 }}>Admin Panel</h2>
      </div>

      {/* මෙනු අයිටම්ස් */}
      <nav style={{ flexGrow: 1, marginTop: '20px', padding: '0 10px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
        {menuItems.map((item) => (
          <button
            key={item.name}
            onClick={() => setCurrentSubPage(item.name)}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              padding: '12px 15px',
              backgroundColor: currentSubPage === item.name ? 'rgba(0,0,0,0.2)' : 'transparent',
              color: '#ffffff',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '14px',
              transition: '0.2s',
              textAlign: 'left'
            }}
          >
            <span>{item.icon}</span>
            {item.name}
          </button>
        ))}
      </nav>

      {/* Logout බටන් එක */}
      <div style={{ padding: '20px', marginTop: 'auto' }}>
        <button
          onClick={onLogoutClick}
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: '#dc2626',
            color: '#fff',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            fontWeight: 'bold',
            transition: '0.2s'
          }}
          onMouseOver={(e) => e.target.style.backgroundColor = '#b91c1c'}
          onMouseOut={(e) => e.target.style.backgroundColor = '#dc2626'}
        >
          🚪 Logout
        </button>
      </div>
    </div>
  );
}
